class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        arr = list(nums)
        i = 0
        while i < n:
            j = i
            bc = bin(arr[i]).count('1')
            while j < n and bin(arr[j]).count('1') == bc:
                j += 1
            arr[i:j] = sorted(arr[i:j])
            i = j
        return all(arr[k] <= arr[k + 1] for k in range(n - 1))
