    elif kind == 2:
        # reverse sorted
        a = sorted(draw(st.lists(st.integers(1, 40), min_size=n, max_size=n)), reverse=True)
    else:
        a = draw(st.lists(st.integers(1, 40), min_size=n, max_size=n))
    return json.dumps(a) + "\n"

