import json

@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    # mix small values (many shared popcounts) with extremes like 1 and 256
    pool = st.one_of(
        st.integers(1, 16),
        st.sampled_from([1, 2, 3, 128, 255, 256]),
        st.integers(1, 256),
    )
    nums = draw(st.lists(pool, min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        lines = inp.strip().split("\n")
        if len(lines) != 1:
            return False
        nums = json.loads(lines[0])
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    if not (1 <= len(nums) <= 100):
        return False
    for x in nums:
        if not isinstance(x, int) or isinstance(x, bool):
            return False
        if not (1 <= x <= 256):
            return False
    return True

def ref(inp):
    # Literal definition: BFS over all arrays reachable by swapping adjacent
    # elements whose popcounts are equal; answer true iff the sorted array is reachable.
    nums = json.loads(inp.strip())
    start = tuple(nums)
    target = tuple(sorted(nums))
    pc = [bin(x).count("1") for x in nums]  # popcount travels with values
    seen = {start}
    frontier = [start]
    while frontier:
        nxt = []
        for state in frontier:
            if state == target:
                return json.dumps(True)
            for i in range(len(state) - 1):
                a, b = state[i], state[i + 1]
                if bin(a).count("1") == bin(b).count("1"):
                    s = list(state)
                    s[i], s[i + 1] = b, a
                    t = tuple(s)
                    if t not in seen:
                        seen.add(t)
                        nxt.append(t)
        frontier = nxt
    return json.dumps(target in seen)
